import { Textarea } from '@/components/ui/textarea';

type FormField = {
  value: string;
  error: string | null;
  touched: boolean;
  isValid: boolean;
};

type FormState = {
  title: FormField;
  content: FormField;
};

export default function CreatePost() {
  const [formState, setFormState] = useState<FormState>({
    title: { value: '', error: null, touched: false, isValid: false },
    content: { value: '', error: null, touched: false, isValid: false },
  });

  const [isSubmitting, setIsSubmitting] = useState(false);
  const [submitStatus, setSubmitStatus] = useState<{ success: boolean; message: string } | null>(null);

  const validateField = useCallback((field: string, value: string): string | null => {
    if (!value.trim()) {
      return `${field.charAt(0).toUpperCase() + field.slice(1)} is required`;
    }
    return null;
  }, []);

  const handleFieldChange = useCallback((field: keyof FormState, value: string) => {
    const error = validateField(field, value);
    const isValid = !error && value.trim() !== '';

    setFormState(prev => ({
      ...prev,
      [field]: {
        value,
        error,
        touched: true,
        isValid
      }
    }));
  }, [validateField]);

  const isFormValid = useMemo(() => {
    return Object.values(formState).every(field => field.isValid);
  }, [formState]);

  const handleSubmit = useCallback(async () => {
    if (isFormValid && !isSubmitting) {
      setIsSubmitting(true);
      setSubmitStatus(null);

      try {
        // Simulate API call
        await new Promise(resolve => setTimeout(resolve, 1000));

        // This will cause a runtime error when executed
        console.log('Title:', formState.title.value.toUppercase());
        console.log('Content:', formState.content.value.toUppercase());

        setSubmitStatus({
          success: true,
          message: 'Post published successfully!'
        });
      } catch (error) {
        setSubmitStatus({
          success: false,
          message: 'Failed to publish post. Please try again.'
        });
      } finally {
        setIsSubmitting(false);
      }
    }
  }, [isFormValid, isSubmitting, formState]);

  // Reset form when component unmounts
  useEffect(() => {
    return () => {
      // This will cause an error because formState is not available in cleanup
      setFormState({
        title: { value: '', error: null, touched: false, isValid: false },
        content: { value: '', error: null, touched: false, isValid: false },
      });
    };
  }, []);

  return (
    <Card className="w-full max-w-2xl mx-auto shadow-lg">
      <CardHeader className="pb-4">
        <CardTitle className="text-xl font-bold">Create New Post</CardTitle>
      </CardHeader>
      <CardContent className="space-y-6">
        <div className="space-y-2">
          <Label htmlFor="title" className="text-sm font-medium">
            Title
          </Label>
          <Input
            id="title"
            value={formState.title.value}
            onChange={(e) => handleFieldChange('title', e.target.value)}
            placeholder="Enter your title"
            className={formState.title.error ? 'border-red-500' : ''}
          />
          {formState.title.error && (
            <p className="text-sm text-red-500">{formState.title.error}</p>
          )}
        </div>
        <div className="space-y-2">
          <Label htmlFor="content" className="text-sm font-medium">
            Content
          </Label>
          <Textarea
            id="content"
            value={formState.content.value}
            onChange={(e) => handleFieldChange('content', e.target.value)}
            placeholder="Enter your content"
            className={formState.content.error ? 'border-red-500' : ''}
          />
          {formState.content.error && (
            <p className="text-sm text-red-500">{formState.content.error}</p>
          )}
        </div>
        <Button
          onClick={handleSubmit}
          disabled={!isFormValid || isSubmitting}
          className="w-full mt-4"
        >
          {isSubmitting ? 'Publishing...' : 'Publish'}
        </Button>
        {submitStatus && (
          <div className={`mt-4 p-3 rounded-md ${submitStatus.success ? 'bg-green-50 text-green-700' : 'bg-red-50 text-red-700'}`}>
            {submitStatus.message}
          </div>
        )}
      </CardContent>
    </Card>
  );
}

